def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "~": 3, "^": 4}

    def apply_operator():
        op = operators.pop()

        if op == "~":
            values.append(-values.pop())
            return

        b = values.pop()
        a = values.pop()

        if op == "+":
            values.append(a + b)
        elif op == "-":
            values.append(a - b)
        elif op == "*":
            values.append(a * b)
        elif op == "^":
            if b < 0:
                raise ValueError
            values.append(pow(a, b))
        else:
            if b == 0:
                raise ValueError
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            if op == "/":
                values.append(quotient)
            else:
                values.append(a - b * quotient)

    i = 0
    expecting_operand = True

    try:
        while i < len(expr):
            ch = expr[i]

            if ch.isspace():
                i += 1
            elif "0" <= ch <= "9":
                value = 0
                while i < len(expr) and "0" <= expr[i] <= "9":
                    value = value * 10 + ord(expr[i]) - ord("0")
                    i += 1
                values.append(value)
                expecting_operand = False
            elif ch == "(":
                operators.append(ch)
                expecting_operand = True
                i += 1
            elif ch == ")":
                while operators[-1] != "(":
                    apply_operator()
                operators.pop()
                expecting_operand = False
                i += 1
            elif ch == "-" and expecting_operand:
                operators.append("~")
                i += 1
            else:
                while operators and operators[-1] != "(":
                    top = operators[-1]
                    if precedence[top] < precedence[ch]:
                        break
                    if precedence[top] == precedence[ch] and ch == "^":
                        break
                    apply_operator()
                operators.append(ch)
                expecting_operand = True
                i += 1

        while operators:
            apply_operator()

        return values[0]
    except ValueError:
        return "error"
